def _install_heavy_dep_stubs() -> None:
    """Mock torch/PIL/etc. to avoid import errors."""
    for mod in (
        "torch",
        "torchvision",
        "numpy",
        "pandas",
        "transformers",
        "safetensors",
        "safetensors.torch",
    ):
        if mod not in sys.modules:
            sys.modules[mod] = MagicMock()
    if "PIL" not in sys.modules:
        pil = MagicMock()
        for sub in ("Image", "ImageDraw", "ImageFont", "PngImagePlugin", "JpegImagePlugin"):
            setattr(pil, sub, MagicMock())
        sys.modules["PIL"] = pil
        sys.modules["Pillow"] = pil

_install_heavy_dep_stubs()

def main():
    try:
        # Import the target module
        from comfy_extras import nodes_string
    except ImportError as e:
        print(f"STATUS: HARNESS_ERROR | Import failed: {e}")
        sys.exit(2)

    # Check if RegexExtract class exists
    if not hasattr(nodes_string, 'RegexExtract'):
        print("STATUS: HARNESS_ERROR | RegexExtract class not found in nodes_string")
        sys.exit(2)

    RegexExtract = nodes_string.RegexExtract

    # Get INPUT_TYPES to understand required arguments
    try:
        input_types = RegexExtract.INPUT_TYPES()
    except Exception as e:
        print(f"STATUS: HARNESS_ERROR | Failed to get INPUT_TYPES: {e}")
        sys.exit(2)

    # Get execute signature
    try:
        sig = inspect.signature(RegexExtract.execute)
        params = list(sig.parameters.keys())
    except Exception as e:
        print(f"STATUS: HARNESS_ERROR | Failed to get execute signature: {e}")
        sys.exit(2)

    # Build arguments based on signature and INPUT_TYPES
    # The execute method typically takes self + the required inputs from INPUT_TYPES
    required_inputs = input_types.get("required", {})

    # Map parameter names to values
    # Note: 'self' is first, then the required inputs
    arg_values = {}

    # Determine which parameters are required inputs (not 'self')
    for param_name in params:
        if param_name == 'self':
            continue
        if param_name in required_inputs:
            # Provide a default value based on the type hint in INPUT_TYPES
            input_def = required_inputs[param_name]
            if isinstance(input_def, tuple) and len(input_def) > 0:
                input_type = input_def[0]
                # Set default values based on type
                if 'STRING' in str(input_type):
                    arg_values[param_name] = ""
                elif 'INT' in str(input_type):
                    arg_values[param_name] = 0
                elif 'FLOAT' in str(input_type):
                    arg_values[param_name] = 0.0
                elif 'BOOLEAN' in str(input_type) or 'BOOL' in str(input_type):
                    arg_values[param_name] = False
                else:
                    arg_values[param_name] = ""
            else:
                arg_values[param_name] = ""

    # Test case 1: No matches (should return empty string or None based on expected behavior)
    print("Testing RegexExtract with no matches...")
    instance = RegexExtract()

    # Test with a pattern that won't match
    test_args = {
        'string': "hello world",
        'regex': "[0-9]+",  # No digits in string
        'case_insensitive': False,
        'multiline': False,
        'dotall': False,
        'group_index': 0
    }

    # Filter to only include parameters that exist in signature
    valid_test_args = {}
    for key, value in test_args.items():
        if key in params:
            valid_test_args[key] = value

    try:
        result = instance.execute(**valid_test_args)

        # Check if result is None (the bug we're looking for)
        if result is None:
            print("STATUS: MISMATCH | expected=string or tuple, actual=None (fall-through detected)")
            sys.exit(1)

        # If result is a tuple, check the first element
        if isinstance(result, tuple):
            if len(result) > 0 and result[0] is None:
                print("STATUS: MISMATCH | expected=string or empty string, actual=None in tuple")
                sys.exit(1)
            # Expected: should return empty string or similar, not None
            if result[0] == "":
                print("STATUS: SAFE | Returns empty string for no matches (expected behavior)")
                sys.exit(0)
            else:
                print(f"STATUS: SAFE | Returns '{result[0]}' for no matches")
                sys.exit(0)
        else:
            if result is None:
                print("STATUS: MISMATCH | expected=string or tuple, actual=None")
                sys.exit(1)
            print(f"STATUS: SAFE | Returns '{result}' for no matches")
            sys.exit(0)

    except Exception as e:
        print(f"STATUS: CRASHED | ExceptionType: {type(e).__name__}: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
